from typing import List
from collections import deque

def findShortestPath(matrix: List[List[int]]) -> int:
    if not matrix or not matrix[0]:
        return -1

    rows = len(matrix)
    cols = len(matrix[0])

    # Check if first or last column has no safe cells
    if not any(matrix[i][0] == 1 for i in range(rows)) or not any(matrix[i][cols-1] == 1 for i in range(rows)):
        return -1

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Queue for BFS: (row, col, distance)
    queue = deque()

    # Mark unsafe cells (landmines and their adjacent cells)
    unsafe = set()
    for i in range(rows):
        for j in range(cols):
            if matrix[i][j] == 0:
                unsafe.add((i, j))
                for di, dj in directions:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < rows and 0 <= nj < cols:
                        unsafe.add((ni, nj))

    # Initialize queue with all safe cells in the first column
    for i in range(rows):
        if matrix[i][0] == 1 and (i, 0) not in unsafe:
            queue.append((i, 0, 1))

    visited = set()
    visited.update(unsafe)

    while queue:
        i, j, dist = queue.popleft()

        # Check if reached last column
        if j == cols - 1:
            return dist

        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < rows and 0 <= nj < cols:
                if (ni, nj) not in unsafe and (ni, nj) not in visited and matrix[ni][nj] == 1:
                    visited.add((ni, nj))
                    queue.append((ni, nj, dist + 1))

    return -1
